    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    for color in counts:
        if color == bg:
            continue
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        edge_runs = []
        for side in ('left', 'right', 'top', 'bottom'):
            vals = ([grid[r][0 if side == 'left' else w-1] for r in range(h)] if side in ('left','right')
                    else grid[0 if side == 'top' else h-1])
            i = 0
            while i < len(vals):
                if vals[i] == bg:
                    i += 1
                    continue
                j = i + 1
                while j < len(vals) and vals[j] == vals[i]:
                    j += 1
                if vals[i] == color and j-i >= 2:
                    edge_runs.append((side, i, j))
                i = j
        # Projection behavior is only established when same-color bars occupy opposite sides.
        paired = any(a[0] == 'left' and b[0] == 'right' and a[2]-a[1] == b[2]-b[1]
                     for a in edge_runs for b in edge_runs) or any(
                     a[0] == 'top' and b[0] == 'bottom' and a[2]-a[1] == b[2]-b[1]
                     for a in edge_runs for b in edge_runs)
        if not paired:
            continue
        # Internal pixels of a different color act as seeds; rays point toward the matching far side.
        for r, c in cells:
            if r in (0, h-1) or c in (0, w-1):
                continue
            seed_colors = [grid[r][c]]
        # Reconstruct seeded color from non-background internal pixels.
        seeds = [(r,c,grid[r][c]) for r in range(1,h-1) for c in range(1,w-1)
                 if grid[r][c] != bg and grid[r][c] != color]
        for r,c,seed in seeds:
            # Emit horizontal ray only, bounded by edge; the marker is an endpoint.
            out[r][c] = 4
            for x in range(c+1,w-1):
                if grid[r][x] != bg:
                    break
                out[r][x] = seed
    return out
