    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)

    def bars(side):
        seq = ([grid[r][0 if side == 'left' else w-1] for r in range(h)]
               if side in ('left','right') else grid[0 if side == 'top' else h-1])
        ans=[]; i=0
        while i<len(seq):
            if seq[i]==bg: i+=1; continue
            j=i+1
            while j<len(seq) and seq[j]==seq[i]: j+=1
            if j-i>=2: ans.append((seq[i],i,j))
            i=j
        return ans
    edges={s:bars(s) for s in ('left','right','top','bottom')}
    pairs=[]
    for a,b in (('left','right'),('top','bottom')):
        for ca,sa,ea in edges[a]:
            for cb,sb,eb in edges[b]:
                if ca==cb and ea-sa==eb-sb:
                    pairs.append((a,b,sa,ea,sb,eb,ca))

    # Match each interior marker with the parallel side-bar(s) whose coordinate
    # covers it. Extend from it away from the nearest edge, replacing the marker
    # with 4. Repeated markers on one ray act independently.
    for a,b,sa,ea,sb,eb,color in pairs:
        for r in range(1,h-1):
            for c in range(1,w-1):
                if grid[r][c]==bg: continue
                if a=='left' and sa<=r<ea:
                    out[r][c]=4
                    for x in range(c+1,w-1):
                        if grid[r][x]!=bg: break
                        out[r][x]=grid[r][c]
                elif a=='top' and sa<=c<ea:
                    out[r][c]=4
                    for y in range(r+1,h-1):
                        if grid[y][c]!=bg: break
                        out[y][c]=grid[r][c]
        # Additional rays originate at each opposite-side bar slot, extending
        # inward through empty cells, ending before the first object.
        if a=='left':
            for r in range(sb,eb):
                for c in range(w-2,0,-1):
                    if grid[r][c]!=bg: break
                    # only project if another marker defines the row's target
                    if any(grid[r][x]!=bg for x in range(1,w-1)):
                        out[r][c]=grid[r][next(x for x in range(1,w-1) if grid[r][x]!=bg)]
        else:
            for c in range(sb,eb):
                for r in range(h-2,0,-1):
                    if grid[r][c]!=bg: break
                    if any(grid[y][c]!=bg for y in range(1,h-1)):
                        out[r][c]=grid[next(y for y in range(1,h-1) if grid[y][c]!=bg)][c]
