    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    def get_runs(side):
        seq = ([grid[r][0 if side == 'left' else w-1] for r in range(h)]
               if side in ('left', 'right') else grid[0 if side == 'top' else h-1])
        runs=[]; i=0
        while i<len(seq):
            if seq[i]==bg:
                i+=1; continue
            j=i+1
            while j<len(seq) and seq[j]==seq[i]: j+=1
            if j-i>=2: runs.append((seq[i],i,j))
            i=j
        return runs

    edges={s:get_runs(s) for s in ('left','right','top','bottom')}
    pairs=[]
    for a,b in (('left','right'),('top','bottom')):
        for ca,sa,ea in edges[a]:
            for cb,sb,eb in edges[b]:
                if ca==cb and ea-sa==eb-sb:
                    pairs.append((a,b,sa,ea,sb,eb))

    for a,b,sa,ea,sb,eb in pairs:
        vertical_sides = a in ('left','right')
        for r in range(1,h-1):
            for c in range(1,w-1):
                marker=grid[r][c]
                if marker==bg: continue
                axis=r if vertical_sides else c
                if sa<=axis<ea:
                    own_side=a; paired_axis=sb+(axis-sa); paired_side=b
                elif sb<=axis<eb:
                    own_side=b; paired_axis=sa+(axis-sb); paired_side=a
                else:
                    continue
                out[r][c]=4
                if vertical_sides:
                    if own_side=='left':
                        for x in range(c-1,0,-1):
                            if grid[r][x]!=bg: break
                            out[r][x]=marker
                    else:
                        for x in range(c+1,w-1):
                            if grid[r][x]!=bg: break
                            out[r][x]=marker
                    # Project the corresponding slot fully inward from the paired edge.
                    if paired_side=='left':
                        for x in range(1,w-1):
                            if grid[paired_axis][x]!=bg: break
                            out[paired_axis][x]=marker
                    else:
                        for x in range(w-2,0,-1):
                            if grid[paired_axis][x]!=bg: break
                            out[paired_axis][x]=marker
                else:
                    if own_side=='top':
                        for y in range(r-1,0,-1):
                            if grid[y][c]!=bg: break
                            out[y][c]=marker
                    else:
                        for y in range(r+1,h-1):
                            if grid[y][c]!=bg: break
                            out[y][c]=marker
                    if paired_side=='top':
                        for y in range(1,h-1):
                            if grid[y][paired_axis]!=bg: break
                            out[y][paired_axis]=marker
                    else:
                        for y in range(h-2,0,-1):
                            if grid[y][paired_axis]!=bg: break
                            out[y][paired_axis]=marker
