            while j < len(vals) and vals[j] == vals[i]:
                j += 1
            if j - i >= 2:
                result.append((vals[i], i, j))
            i = j
        return result

    edges = {side: find_runs(side) for side in ('left', 'right', 'top', 'bottom')}
    pairs = []
    for a, b in (('left', 'right'), ('top', 'bottom')):
        for ca, sa, ea in edges[a]:
            for cb, sb, eb in edges[b]:
                if ca == cb and ea - sa == eb - sb:
                    pairs.append((a, b, sa, ea, sb, eb))

    def ray(r, c, side, color, stop_at_obstacle=True):
        dr, dc = {'left': (0, -1), 'right': (0, 1), 'top': (-1, 0), 'bottom': (1, 0)}[side]
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w:
            if grid[rr][cc] != bg:
                break
            out[rr][cc] = color
            rr += dr
            cc += dc

