 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Identify the uncommon marker color, distinct from background and edge bars.
    edge_colors = set(grid[0]) | {grid[r][0] for r in range(h)} | {grid[r][w-1] for r in range(h)} | set(grid[h-1])
    marker_counts = {c:n for c,n in counts.items() if c != bg and c not in edge_colors}
    if not marker_counts:
        return out
    marker = min(marker_counts, key=marker_counts.get)
    positions = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == marker]

    # Mark all interior marker points as endpoints. On each row, connect
    # same-row endpoints (including a marker touching the edge) with their color.
    for r in range(h):
        cols = [c for rr,c in positions if rr == r]
        if not cols:
            continue
        for c in cols:
            if 0 < r < h-1 and 0 < c < w-1:
                out[r][c] = 4
        if len(cols) >= 2:
            left, right = min(cols), max(cols)
            for c in range(left+1, right):
                if grid[r][c] == bg:
                    out[r][c] = marker

    # A horizontal edge guide at the upper-right projects its marker color
    # inward across the rows spanned by the marker pattern; the guide remains intact.
    top_nonbg = [c for c,v in enumerate(grid[0]) if v != bg]
    bottom_nonbg = [c for c,v in enumerate(grid[h-1]) if v != bg]
    if top_nonbg and bottom_nonbg and min(bottom_nonbg) < min(top_nonbg):
        start = min(top_nonbg) + 1
        end = max(top_nonbg) + 1
        r0 = max(1, min(r for r,c in positions)-1)
        r1 = min(h-1, max(r for r,c in positions)+1)
        for r in range(r0, r1):
            for c in range(start, end):
                if grid[r][c] == bg:
                    out[r][c] = marker
    return out
